mapper.select:
SELECT a.id,
       a.operator_id,
       u.nickname AS operator_nickname,
       u.avatar_url AS operator_avatar_url,
       a.action,
       a.target_type,
       a.target_id,
       a.request_id,
       a.detail_json,
       a.created_at
FROM audit_logs a
         JOIN users u ON u.id = a.operator_id


        AND a.operator_id = #{operatorId}


        AND a.action = #{action}


        AND a.target_type = #{targetType}


        AND a.target_id = #{targetId}


        AND a.created_at >= #{from}


        AND a.created_at <= #{to}


ORDER BY a.created_at DESC, a.id DESC
